/**
 * The phase-2 EXIT GATE (compiled-builder, plan "Exit gate" bullet 1): every correct baseline transform, re-expressed as a
 * combinator pipeline and shown to compute the same output as the jq it replaces, on fixture rows of the REAL input type.
 *
 * The population is the 41 transforms of baseline flows (E0.12) that ran green AND whose reads all exist upstream — the
 * honest set: a transform from a flow that was wrong is not a target to reproduce. `original` is the jq verbatim from the
 * baseline model (`phase-2-ir-and-combinators/logs/reexpress-originals.txt`); it is run exactly as the compiler ran it.
 *
 * ⚠ Types. Each source's type is the one the PRODUCTION checker gives it (`REEXPRESS_SOURCE_TYPES`, generated by
 * `scenarios/reexpress-types.ts` and checked against the live catalogue). Six sources were operations drafted during the
 * baseline and have since been deleted, so no live type exists; for those the type is DECLARED here with every column
 * `Option` — the strictest a described reader can be, which makes the pipeline say what null means everywhere.
 *
 * ⚠ Verdicts. On every fixture the LOWERING must equal the EVALUATOR (the combinators' own soundness). Against the
 * original: equal, unless the fixture is marked `diverges`, and then they must DIFFER — a divergence claim that does not
 * reproduce is false. A divergence names what the original gets wrong (or cannot say) on that input; each one is a case
 * where jq's quirks (null ordered first, `tostring` of null, null in a list) reached an output silently.
 *
 * A transform the combinators cannot express is `notAdmitted` with the reason, never forced into a near miss.
 */
import { T, type Ty } from "../typecheck/types.js";
import type { Literal, Part, Pipeline } from "./combinators.js";
import { REEXPRESS_SOURCE_TYPES } from "./reexpress-types.js";

export interface ReexpressFixture { name: string; input: unknown; diverges?: string }
interface Base { id: string; source: string; original: string; note?: string }
export type Reexpression =
  | (Base & { pipeline: Pipeline; fixtures: ReexpressFixture[] })
  /** The original returns an object of several values; each is re-expressed as its own pipeline (a step each). */
  | (Base & { fields: Record<string, Pipeline>; fixtures: ReexpressFixture[] })
  | (Base & { notAdmitted: string });

const lit = (value: string | number | boolean): Literal => ({ value, from: "goal" });
const tx = (text: string): Part => ({ text });
const f = (field: string): Part => ({ field });
const opt = (field: string, orElse = "", pre = "", post = ""): Part => ({ opt: field, pre, post, else: orElse });
const O = T.option;

/** Types of the six deleted sources: DECLARED, every column nullable (see the header). */
const DECLARED: Record<string, Ty> = {
  "hr_demo.employee_directory": T.rows(T.record({ employee_id: O(T.int()), full_name: O(T.text()), work_email: O(T.text()), employment_status: O(T.text()) })),
  "legal_demo.contract_identity_counterparty_value_end": T.rows(T.record({ contract_code: O(T.text()), counterparty_name: O(T.text()), contract_value_cents: O(T.int()), contract_end_date: O(T.date()) })),
  "support_demo.csat_survey_rows": T.rows(T.record({ team_code: O(T.text()), surveyed: O(T.bool()), score: O(T.int()) })),
  "support_demo.all_csat_responses": T.rows(T.record({ team_name: O(T.text()), surveyed: O(T.bool()), csat_score: O(T.int()) })),
  "hiring_demo.candidate_application_rows": T.rows(T.record({ hiring_manager_email: O(T.text()), candidate_name: O(T.text()), current_pipeline_stage: O(T.text()), application_status: O(T.text()), requisition_role: O(T.text()) })),
  "hiring_demo.applications_prior_month": T.rows(T.record({ application_status: O(T.text()), current_stage: O(T.text()), candidate_id: O(T.int()) })),
};
/** The input type of a case's source: live where it exists, declared where it was deleted. */
export function sourceType(ref: string): { ty: Ty; declared: boolean } {
  const live = REEXPRESS_SOURCE_TYPES[ref];
  if (live) return { ty: live, declared: false };
  const d = DECLARED[ref];
  if (!d) throw new Error(`no type for source ${ref}`);
  return { ty: d, declared: true };
}

