/** Does a fixture value inhabit a type? A nullable field may be absent (the engine cannot tell absent from null). */
export function conforms(v: unknown, ty: Ty, at = "$"): string | null {
  if (ty.t === "Option") return v === null || v === undefined ? null : conforms(v, ty.of, at);
  if (v === null || v === undefined) return `${at}: null where ${ty.t} is required`;
  switch (ty.t) {
    case "Rows": case "List": {
      if (!Array.isArray(v)) return `${at}: not a list`;
      for (const [i, x] of v.entries()) { const e = conforms(x, ty.of, `${at}[${i}]`); if (e) return e; }
      return null;
    }
    case "Record": {
      if (typeof v !== "object" || Array.isArray(v)) return `${at}: not a record`;
      for (const k of Object.keys(v as object)) if (!ty.fields[k]) return `${at}.${k}: not a field of the source`;
      for (const [k, ft] of Object.entries(ty.fields)) { const e = conforms((v as Record<string, unknown>)[k], ft, `${at}.${k}`); if (e) return e; }
      return null;
    }
    case "Int": return Number.isInteger(v) ? null : `${at}: not an integer`;
    case "Number": return typeof v === "number" ? null : `${at}: not a number`;
    case "Bool": return typeof v === "boolean" ? null : `${at}: not a boolean`;
    case "Date": return typeof v === "string" && /^\d{4}-\d{2}-\d{2}$/.test(v) ? null : `${at}: not a date`;
    case "DateTime": return typeof v === "string" && /^\d{4}-\d{2}-\d{2}T/.test(v) ? null : `${at}: not a datetime`;
    case "Text": case "Address": case "Key": case "Month": return typeof v === "string" ? null : `${at}: not text`;
    default: return null;
  }
}

// ── the verdict (shared by the local-jq test and the Kestra proof, so both judge exactly the same thing) ──

/** The transform wrapper, exactly as `lowerTransformProgram` applies it to every transform program. */
export const wrapTransform = (program: string) => `(${program}) | if type == "string" then {text: .} else . end`;
/** Runs a jq PROGRAM (already wrapped) over an input. Local jq in tests; Kestra in the proof. */
export type ProgramRunner = (program: string, input: unknown) => Promise<unknown>;

export interface ReexpressResult { id: string; fixture: string; ok: boolean; kind: "agree" | "diverges-as-declared" | "FAIL"; detail?: string }
export interface ReexpressReport { results: ReexpressResult[]; expressed: number; notAdmitted: Array<{ id: string; reason: string }> }

/**
 * Judge every case. Per fixture: the fixture inhabits the source type; each pipeline types as a transform; its lowering,
 * run, equals its evaluation; and against the ORIGINAL it is equal — or, where the fixture declares a divergence, different.
 * `lowerFn`/`evalFn`/`typeFn` are injected so the negative control can perturb the lowering.
 */
export async function judgeReexpressions(
  run: ProgramRunner,
  deps: { lower: (ty: Ty, p: Pipeline) => string; evaluate: (input: unknown, p: Pipeline) => unknown; type: (ty: Ty, p: Pipeline) => { ok: boolean; error?: string; at?: number }; equal: (a: unknown, b: unknown) => boolean },
  cases: Reexpression[] = REEXPRESSIONS,
): Promise<ReexpressReport> {
  const results: ReexpressResult[] = [];
  const notAdmitted: ReexpressReport["notAdmitted"] = [];
  let expressed = 0;
  for (const c of cases) {
    if ("notAdmitted" in c) { notAdmitted.push({ id: c.id, reason: c.notAdmitted }); continue; }
    expressed++;
    const { ty } = sourceType(c.source);
    const parts: Array<[string | null, Pipeline]> = "fields" in c ? Object.entries(c.fields) : [[null, c.pipeline]];
    const fail = (fixture: string, detail: string) => results.push({ id: c.id, fixture, ok: false, kind: "FAIL", detail });
    const typed = parts.map(([k, p]) => [k, deps.type(ty, p)] as const).find(([, r]) => !r.ok);
    if (typed) { fail("(typing)", `${typed[0] ?? "pipeline"} does not type at stage ${typed[1].at}: ${typed[1].error}`); continue; }
    for (const fx of c.fixtures) {
      const bad = conforms(fx.input, ty);
      if (bad) { fail(fx.name, `the fixture is not a value of the source type — ${bad}`); continue; }
      let orig: unknown;
      try { orig = await run(wrapTransform(c.original), fx.input); } catch (e) { fail(fx.name, `the ORIGINAL failed: ${(e as Error).message.slice(0, 200)}`); continue; }
      let ours: Record<string, unknown> | unknown = {};
      let sound = true;
      for (const [k, p] of parts) {
        let lowered: unknown;
        // A split field is compared as the VALUE it stands for, so it is run bare; a whole transform runs wrapped, as compiled.
        try { lowered = await run(k === null ? wrapTransform(deps.lower(ty, p)) : deps.lower(ty, p), fx.input); } catch (e) { fail(fx.name, `the lowering failed: ${(e as Error).message.slice(0, 200)}`); sound = false; break; }
        const evaluated = deps.evaluate(fx.input, p);
        const evalWrapped = k === null && typeof evaluated === "string" ? { text: evaluated } : evaluated;
        if (!deps.equal(lowered, evalWrapped)) { fail(fx.name, `UNSOUND — lowering ${JSON.stringify(lowered).slice(0, 200)} ≠ evaluator ${JSON.stringify(evalWrapped).slice(0, 200)}`); sound = false; break; }
        if (k === null) ours = lowered; else (ours as Record<string, unknown>)[k] = lowered;
      }
      if (!sound) continue;
      const same = deps.equal(orig, ours);
      if (fx.diverges) {
        results.push(same
          ? { id: c.id, fixture: fx.name, ok: false, kind: "FAIL", detail: `declared to diverge, but the outputs are EQUAL — the divergence claim is false` }
          : { id: c.id, fixture: fx.name, ok: true, kind: "diverges-as-declared", detail: fx.diverges });
      } else {
        results.push(same ? { id: c.id, fixture: fx.name, ok: true, kind: "agree" }
          : { id: c.id, fixture: fx.name, ok: false, kind: "FAIL", detail: `original ${JSON.stringify(orig).slice(0, 260)}\n    ours     ${JSON.stringify(ours).slice(0, 260)}` });
      }
    }
  }
  return { results, expressed, notAdmitted };
}

/** Every (program, input) the judgement will run — so an engine can run them all in one execution first. */
export function reexpressPrograms(lower: (ty: Ty, p: Pipeline) => string, cases: Reexpression[] = REEXPRESSIONS): Array<{ program: string; input: unknown }> {
  const out: Array<{ program: string; input: unknown }> = [];
  for (const c of cases) {
    if ("notAdmitted" in c) continue;
    const { ty } = sourceType(c.source);
    const parts: Array<[string | null, Pipeline]> = "fields" in c ? Object.entries(c.fields) : [[null, c.pipeline]];
    for (const fx of c.fixtures) {
      out.push({ program: wrapTransform(c.original), input: fx.input });
      for (const [k, p] of parts) {
        let lowered: string;
        try { lowered = lower(ty, p); } catch { continue; } // an ill-typed pipeline is reported by the judgement itself
        out.push({ program: k === null ? wrapTransform(lowered) : lowered, input: fx.input });
      }
    }
  }
  return out;
}
